// Prints the rhyme tables of parser.js (VietnameseParser.DECODINGS) as Kotlin source: node tools/golden/gen_tables.mjs > app/src/main/java/helium314/keyboard/qatt/Decodings.kt
import { VietnameseParser as P } from './load.mjs';
const q = s => JSON.stringify(s.normalize('NFC')).replace(/\$/g, '\\$');
let s = `// SPDX-License-Identifier: GPL-3.0-only
// Generated by tools/golden/gen_tables.mjs from VietnameseParser.DECODINGS of qtng/qatt (js/parser.js): do not edit.

package helium314.keyboard.qatt

/** The rhyme tables of the known decodings: DECODINGS[name][row][column] (row i = shape SHAPES[i], column + 2 = marking stroke, a sixth column is the plain shape). */
internal val DECODINGS: Map<String, List<List<String>>> = mapOf(\n`;
s += Object.entries(P.DECODINGS).map(([name, t]) => `    ${q(name)} to listOf(\n` + t.map(r => `        listOf(${r.map(q).join(', ')})`).join(',\n') + '\n    )').join(',\n');
s += '\n)\n';
process.stdout.write(s);
